sql.where:
CUST_CODE = #{search.custCode}

    AND TO_DATE(CALLDATE, 'YYYY-MM-DD HH24:MI:SS') >= TO_DATE(#{search.startDate}, 'YYYY-MM-DD')


    AND TO_DATE(CALLDATE, 'YYYY-MM-DD HH24:MI:SS') <= TO_DATE(#{search.endDate} || ' 23:59:59', 'YYYY-MM-DD HH24:MI:SS')

mapper.select:
SELECT L.ID AS LMS_ID, C.CALLDATE, C.CLID, C.RESULT, C.CONTEXT, TO_DATE(C.CALLDATE, 'YYYY-MM-DD HH24:MI:SS') AS CALL_DATETIME FROM LMS_LOG L INNER JOIN CALL_LOG_D C ON L.CLID = C.CLID AND TO_DATE(C.CALLDATE, 'YYYY-MM-DD HH24:MI:SS') >= L.CREATED_DATE AND TO_DATE(C.CALLDATE, 'YYYY-MM-DD HH24:MI:SS') <= L.CREATED_DATE + INTERVAL '1' DAY WHERE L.ID IN
#{id}
AND C.CUST_CODE = #{custCode} ORDER BY L.ID, TO_DATE(C.CALLDATE, 'YYYY-MM-DD HH24:MI:SS') DESC
